import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"TopicSubscription — takoform_topic_subscription","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/topic/topic-subscription.md","filePath":"proposals/topic/topic-subscription.md"}'),r={name:"proposals/topic/topic-subscription.md"};function s(n,e,c,d,h,l){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="topicsubscription-—-takoform-topic-subscription" tabindex="-1">TopicSubscription — <code>takoform_topic_subscription</code> <a class="header-anchor" href="#topicsubscription-—-takoform-topic-subscription" aria-label="Permalink to &quot;TopicSubscription — `takoform_topic_subscription`&quot;">​</a></h1><blockquote><p>Historical/deferred candidate (English-only). This non-Edge Form is not in the current official Edge16 corpus or Current navigation.</p></blockquote><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team wires its queue to a topic: every message published to the topic that matches the subscription&#39;s filter lands in the team&#39;s PullQueue, and the team&#39;s consumers drain it at their own pace.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Subscription is activation of the fanout edge; deleting the subscription detaches it and never deletes the topic or the target queue.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>topic</code> and <code>target</code> are immutable; changing either replaces the attachment. <code>topic</code> references a <a href="./topic.html">Topic</a>. <code>target</code> is the closed exact <code>{apiVersion, kind, name}</code> reference to a resource providing <code>queue.pull@1.0.0</code> — in this retained candidate a <code>PullQueue</code> of <code>queue.forms.takoform.com</code>. The reference carries its group explicitly, so the cross-family edge is representable as-is (<a href="./../../spec/binding-contract/">binding contract</a>); the relation requires the Interface the target provides and is UID-pinned under the Host API v1 relation rules. At most one subscription may bind one (topic, target) pair; a second is refused — a union of two filter policies therefore needs two targets.</p><p>Delivery: for each accepted publish that matches, the subscription sends into the target queue. The delivered message is a new queue message with the queue&#39;s own identity and receive count, carrying the published body and attributes unchanged. Delivery is at-least-once per subscription, so one publish may land in the queue twice; consumers must be idempotent. A failed send is retried after <code>retryDelaySeconds</code> (0..3600); <code>maxRetries</code> (0..100) counts retries only, so a message is attempted at most <code>1 + maxRetries</code> times — mirroring the edge QueueConsumer&#39;s counting rule. An exhausted message goes to <code>deadLetter</code> (a PullQueue reference of the same exact shape, distinct from <code>target</code>) when declared and is dropped otherwise; the dead-letter copy is a new message there with its own identity, acceptance timestamp, and receive count.</p><p><code>filterPolicy</code> is an optional closed map from attribute name to a non-empty list of at most 16 candidate strings, over at most 10 named attributes. A message matches when, for EVERY named attribute, the message carries that attribute and its value equals one of the listed candidates — exact, case-sensitive string equality/inclusion; attributes the policy does not name are unconstrained; an absent policy matches every message. There is no numeric range, prefix, negation, or content/JSON-path filtering. A non-matching message is filtered: not delivered, not dead-lettered, and final. <code>filterPolicy</code>, the retry fields, and <code>deadLetter</code> update in place; a filter change applies to publishes accepted after the change.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Filter, retry, and dead-lettering decide what a subscriber observes under load and failure; they must travel with the subscription edge itself, as the edge QueueConsumer established for its consumer edge.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>HTTPS push delivery to an author-named endpoint is recorded here and deliberately deferred: it changes the security surface and needs a fixed endpoint-authentication shape before it can be one complete contract. A richer filter grammar (ranges, prefixes, negation, payload paths) changes what &quot;matches&quot; means and is a different subscription Form or a new exact Interface generation, never a widening of this closed grammar.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting the referenced topic, target queue, or dead-letter queue while this subscription exists must fail with <code>dependency_in_use</code>. <code>deadLetter</code> equal to <code>target</code> is refused: a delivery that failed into the target cannot dead-letter into the same place. A target deleted and re-created under the same name is a different incarnation: the subscription stays pinned, reports <code>ExternalChange</code> or <code>DependencyMissing</code> per the Host API v1 relation rules, and only a re-apply re-pins it.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The per-subscription filtered fanout of every major provider&#39;s pub/sub topic. The withdrawn v1alpha2 epoch had no subscription kind. The Edge family&#39;s QueueConsumer for contrast: that attachment has the host invoke a worker handler; this one feeds a pull queue and lets consumers come to the messages.</p>',22)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
